div.script:
function searchAutocomplete(autofocus = false) {
    return {
        query: '',
        logos: [],
        sectors: [],
        tags: [],
        open: false,
        selectedIndex: -1,

        init() {
            // Only autofocus on non-touch devices
            if (autofocus && !this.isTouchDevice()) {
                this.$refs.searchInput.focus();
            }
        },

        isTouchDevice() {
            return (('ontouchstart' in window) ||
                    (navigator.maxTouchPoints > 0) ||
                    (navigator.msMaxTouchPoints > 0));
        },

        async fetchSuggestions() {
            if (this.query.length < 1) {
                this.clearSuggestions();
                this.open = false;
                this.selectedIndex = -1;
                return;
            }

            try {
                const response = await fetch(`/api/search/suggestions?q=${encodeURIComponent(this.query)}`);
                const suggestions = await response.json();
                this.logos = suggestions.logos;
                this.sectors = suggestions.sectors;
                this.tags = suggestions.tags;
                this.open = this.allSuggestions.length > 0;
                this.selectedIndex = -1;
            } catch (error) {
                console.error('Error fetching suggestions:', error);
                this.clearSuggestions();
                this.open = false;
            }
        },

        selectNext() {
            if (this.allSuggestions.length === 0) return;
            this.selectedIndex = (this.selectedIndex + 1) % this.allSuggestions.length;
        },

        selectPrevious() {
            if (this.allSuggestions.length === 0) return;
            this.selectedIndex = this.selectedIndex <= 0 ? this.allSuggestions.length - 1 : this.selectedIndex - 1;
        },

        submitSelected() {
            if (this.selectedIndex >= 0 && this.allSuggestions[this.selectedIndex]) {
                this.navigateToSuggestion(this.allSuggestions[this.selectedIndex]);
            } else {
                // Submit the form normally
                this.$el.closest('form').submit();
            }
        },

        suggestionUrl(suggestion) {
            if (suggestion.type === 'logo') {
                return `https://worldvectorlogo.com/search?q=${encodeURIComponent(suggestion.name)}`;
            }

            const route = suggestion.type === 'sector'
                ? `https://worldvectorlogo.com/sectors/__slug__`
                : `https://worldvectorlogo.com/tag/__slug__`;
            return route.replace('__slug__', encodeURIComponent(suggestion.slug));
        },

        navigateToSuggestion(suggestion) {
            window.location.href = this.suggestionUrl(suggestion);
        },

        suggestionIndex(suggestion) {
            return this.allSuggestions.findIndex(item => item.type === suggestion.type && item.slug === suggestion.slug);
        },

        clearSuggestions() {
            this.logos = [];
            this.sectors = [];
            this.tags = [];
        },

        get allSuggestions() {
            return [...this.logos, ...this.sectors, ...this.tags];
        }
    }
}
